-- Source: FTC Enforcement Actions and Data Sets (1200 rows)
-- Generated by gen_mart_models.py

-- DEDUP (2026-08-18 verification): 100% of the 196-row surplus is exactly 4
-- distinct FTC news/blog/event items (RESPONDENT/CASE_TYPE/STATUS/TOPIC/EIN all
-- blank -- these are not enforcement actions) each repeated exactly 50x --
-- a "pinned item shown on every crawled listing page" pattern, single load run
-- (1 distinct _SOURCE_RUN_ID). Live: 1,200 rows / 1,004 distinct -- single-load
-- duplication, exact dups carry no information. Flag: even after dedup, the
-- sampled rows hold no actual FTC case/enforcement records, same gap as USCIS.
with source as (
    select * from {{ source('ripple_raw', 'FED_FTC_DATASETS') }}
    qualify row_number() over (
        partition by ACTION_NAME, RESPONDENT, DATE_FILED, CASE_TYPE, STATUS,
                     TOPIC, DOCUMENT_URL, EIN
        order by _INGESTED_AT) = 1
)

select
    ACTION_NAME as action_name,
    RESPONDENT as respondent,
    try_to_date(DATE_FILED) as date_filed,
    CASE_TYPE as case_type,
    STATUS as status,
    TOPIC as topic,
    DOCUMENT_URL as document_url,
    EIN as ein
from source
